import sys,json,os
from pathlib import Path
sys.path.insert(0,'/private/tmp/ceo-skill-source-bindings')
from app.config import load_env_file
from app.agent_cli import build_role_server
from mcp.server.fastmcp import FastMCP
from mcp.types import ToolAnnotations
root=Path(__file__).parent;case=sys.argv[1]
load_env_file(Path('/Users/derek/Services/ceo-agent-service/.env'))
registered=build_role_server('audit',task_id=1,db_path=root/(case+'-revised')/'audit.sqlite3',execution_generation='initial')
mcp=FastMCP('agent_cli');read=ToolAnnotations(readOnlyHint=True,destructiveHint=False,idempotentHint=True,openWorldHint=False)
def log(name,args,result):
    with (root/'calls.jsonl').open('a') as f:f.write(json.dumps({'case':case,'name':name,'args':args,'result':result},ensure_ascii=False)+'\n')
    return result
@mcp.tool(annotations=read)
def read_skill(path:str|None=None,name:str|None=None)->dict[str,object]:
    value=registered._tool_manager.get_tool('read_skill').fn(path=path,name=name)
    return log('read_skill',{'path':path,'name':name},value)
@mcp.tool(annotations=read)
def read_text_file(path:str)->dict[str,object]:
    value=registered._tool_manager.get_tool('read_text_file').fn(path=path)
    return log('read_text_file',{'path':path},value)
@mcp.tool(annotations=read)
def read_system_action_contract(capability:str,operation:str|None=None)->dict[str,object]:
    value=registered._tool_manager.get_tool('read_system_action_contract').fn(capability=capability,operation=operation)
    return log('read_system_action_contract',{'capability':capability,'operation':operation},value)
@mcp.tool(annotations=read)
def read_dingtalk_messages(conversation_id:str,title:str='',single_chat:bool=False,limit:int=50)->dict[str,object]:
    if conversation_id!='cid-audit':raise ValueError('unknown anonymous conversation')
    manifest=json.loads((root/'corrected_candidate_manifest.json').read_text())
    candidate=next(x['candidate'] for x in manifest['cases'] if x['case']==case)
    snapshot=manifest['snapshot']
    return log('read_dingtalk_messages',{'conversation_id':conversation_id,'title':title,'single_chat':single_chat,'limit':limit},{'messages':[{'message_id':'msg-audit','sender':'Derek','text':manifest['request'],'create_time':manifest['clock'],'raw_payload':snapshot}]})
@mcp.tool(annotations=read)
def read_dingtalk_user_profiles(user_ids:list[str])->dict[str,object]:
    manifest=json.loads((root/'corrected_candidate_manifest.json').read_text());s=manifest['snapshot']
    if not set(user_ids).issubset({s['recipient'],s['applicant_user_id']}):raise ValueError('unknown anonymous user')
    return log('read_dingtalk_user_profiles',{'user_ids':user_ids},{'result':[{'orgEmployeeModel':{'name':s['applicant_name'],'userId':s['applicant_user_id'],'openDingtalkId':s['recipient'],'isActive':True}}],'captured_at':manifest['clock']})
if __name__=='__main__':mcp.run(transport='stdio')
